#include <iostream>
#include <array>
#include <algorithm>

int main() {
    const std::array<int, 4> values = {1, 2, 3, 4};

    // Lambda assigned to variable
    auto printDoubled = [](int i) {
        std::cout << i * 2 << "\n";
    };

    // Execute assigned lambda directly
    printDoubled(10);

    // Pass lambda to std::for_each (nonmodifying sequence iteration)
    std::for_each(values.cbegin(), values.cend(), printDoubled);

    // Capture local variable by reference to accumulate sum
    int sum = 0;
    std::for_each(values.cbegin(), values.cend(), [&sum](int i) {
        sum += i;
    });

    std::cout << "sum is " << sum << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>

int main() {
    std::vector<int> data(5);

    // 1. Numerical: std::iota
    std::iota(data.begin(), data.end(), 1); // 1, 2, 3, 4, 5

    // 2. Nonmodifying: std::all_of
    bool allPositive = std::all_of(data.cbegin(), data.cend(), [](int x) {
        return x > 0;
    });
    std::cout << "All positive: " << (allPositive ? "true" : "false") << "\n";

    // 3. Mutating: std::transform
    std::transform(data.begin(), data.end(), data.begin(), [](int x) {
        return x * x;
    }); // 1, 4, 9, 16, 25

    // 4. Numerical: std::accumulate
    int sumOfSquares = std::accumulate(data.cbegin(), data.cend(), 0);
    std::cout << "Sum of squares: " << sumOfSquares << "\n";

    // 5. Sorting & Binary search: std::binary_search
    bool hasNine = std::binary_search(data.cbegin(), data.cend(), 9);
    std::cout << "Contains 9: " << (hasNine ? "true" : "false") << "\n";

    return 0;
}
